import * as U from '../ui.js';
import {groupStudyTasks} from '../study-groups.js';
let scope='all',selectedCourse='';const weekStart=new Date(U.TODAY+'T12:00Z');weekStart.setUTCDate(weekStart.getUTCDate()-((weekStart.getUTCDay()+6)%7));const weekEnd=new Date(weekStart);weekEnd.setUTCDate(weekEnd.getUTCDate()+7);
const addStudy=(label,courseId)=>U.button(label,'tasks','',{task_type:'study',...(courseId?{course_id:courseId}:{})});
const update=U.mount(()=>{let tasks=U.db.tasks.filter(t=>t.task_type==='study');if(scope==='week')tasks=tasks.filter(t=>!t.planned_start_at||(U.day(t.planned_start_at)>=weekStart.toISOString().slice(0,10)&&U.day(t.planned_start_at)<weekEnd.toISOString().slice(0,10)));let groups=groupStudyTasks(tasks,U.db.courses,U.db.tasks);if(selectedCourse)groups=groups.filter(g=>(g.courseId||'__personal')===selectedCourse);const shown=groups.flatMap(g=>g.tasks),done=shown.filter(t=>t.status==='done').length,minutes=shown.filter(t=>t.planned_start_at&&t.status!=='cancelled').reduce((n,t)=>n+Number(t.estimated_minutes||0),0);return U.heading('Build momentum','Study, subject by subject.','Your study tasks, organized by course. Pick a subject and take the next small step.',addStudy('Add study task',selectedCourse==='__personal'?'':selectedCourse))+`<div class="study-summary"><div><strong>${shown.length}</strong><span>study tasks</span></div><div><strong>${groups.length}</strong><span>subjects</span></div><div><strong>${done}</strong><span>completed</span></div><div><strong>${minutes}<small> min</small></strong><span>planned time</span></div></div><div class="toolbar"><div class="tabs"><button data-scope="all" class="${scope==='all'?'active':''}">All study tasks</button><button data-scope="week" class="${scope==='week'?'active':''}">This week</button></div><label class="study-course-filter"><span>Subject</span><select id="study-course" aria-label="Filter study tasks by subject"><option value="">All subjects</option>${U.db.courses.map(c=>`<option value="${c.id}" ${selectedCourse===c.id?'selected':''}>${U.esc(c.course_code)} · ${U.esc(c.name)}</option>`).join('')}<option value="__personal" ${selectedCourse==='__personal'?'selected':''}>Personal study</option></select></label></div><div class="study-subject-grid">${groups.map(group=>{let completed=group.tasks.filter(t=>t.status==='done').length;return `<section class="card study-subject subject-colored" style="${U.subjectStyle(group.courseId)}" data-course-id="${U.esc(group.courseId||'personal')}"><header class="study-subject-header"><div class="study-subject-icon">${U.icon('book')}</div><div class="study-subject-heading"><div class="eyebrow">${U.esc(group.course?.course_code||'YOUR OWN PACE')}</div><h2>${group.course?`<a href="course.html?id=${group.courseId}">${U.esc(group.course.name)}</a>`:'Personal study'}</h2></div>${U.tag(group.tasks.length+' task'+(group.tasks.length===1?'':'s'),'blue')}</header><div class="study-subject-progress"><span>${completed} of ${group.tasks.length} completed</span><span>${Math.round(completed/group.tasks.length*100)}%</span></div><div class="progress"><i style="width:${completed/group.tasks.length*100}%"></i></div><div class="study-subject-tasks">${group.tasks.map(t=>`<article class="study-subject-task"><div class="study-task-plan">${U.icon(t.planned_start_at?'clock':'calendar')}<span>${t.planned_start_at?`${U.date(U.day(t.planned_start_at),{weekday:'short',day:'numeric',month:'short'})} · ${U.time(t.planned_start_at)}${t.planned_end_at?'–'+U.time(t.planned_end_at):''}`:'Not scheduled yet'}${t.estimated_minutes?' · '+t.estimated_minutes+' min':''}</span>${t.status==='cancelled'?U.tag('Cancelled'):''}</div>${U.taskRow({...t,course_id:group.courseId})}</article>`).join('')}</div><footer class="study-subject-footer">${addStudy('Add study task',group.courseId).replace('btn primary','btn soft')}</footer></section>`}).join('')||`<section class="card study-no-tasks"><div class="course-symbol">${U.icon('study')}</div><h2>No study tasks here yet.</h2><p class="muted">Add a task for this subject, or turn an assignment into smaller study steps.</p>${addStudy('Add study task',selectedCourse==='__personal'?'':selectedCourse)}</section>`}</div><div class="note" style="margin-top:24px">${U.icon('study')}<span>Need a starting point? Open an assignment and choose “Break into study tasks.” Each step stays with its subject, and you can give it a time whenever you’re ready.</span><a href="tasks.html" class="text-link" style="flex-shrink:0">Open assignments →</a></div>`});
document.addEventListener('click',e=>{let b=e.target.closest('[data-scope]');if(b){scope=b.dataset.scope;update()}});document.addEventListener('change',e=>{if(e.target.id==='study-course'){selectedCourse=e.target.value;update()}});
